3	/**
4	 * Thrown when a create-owner request names a city that already holds the maximum number
5	 * of owners, so no further owners may be added to it. Handled by
6	 * {@link CityAtCapacityExceptionHandler}, which responds 409.
7	 */
8	public class CityAtCapacityException extends Exception {
9	
10	    private final String city;
11	
12	    private final int capacity;
13	
14	    public CityAtCapacityException(String city, int capacity) {
15	        super("City is at capacity (" + capacity + " owners): " + city);
16	        this.city = city;
17	        this.capacity = capacity;
18	    }
19	
20	    public String getCity() {
21	        return this.city;
22	    }
23	
24	    public int getCapacity() {
25	        return this.capacity;
26	    }
27	}
