9	public class CityAtCapacityExceptionHandler {
10	
11	    public void handle(@Parameter CityAtCapacityException ex,
12	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
13	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.CONFLICT,
14	                "The owner's city has reached its maximum number of owners");
15	        response.send(ResponseEntity.status(HttpStatus.CONFLICT).body(detail));
16	    }
17	}
