306	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership level}: at
307	     * creation a new owner's level cannot exceed one above the highest level then held by an
308	     * existing member of its household (same last name and postcode). Null when no cap
309	     * applies, i.e. the household had no existing members. Captured at creation.
310	     */
311	    public Integer getMembershipLevelCap() {
312	        return this.membershipLevelCap;
313	    }
314	
315	    public void setMembershipLevelCap(Integer membershipLevelCap) {
316	        this.membershipLevelCap = membershipLevelCap;
317	    }
