319	    /**
320	     * Whether this owner was created as part of a bulk signup: {@code true} when more
321	     * than 80 owners had already been registered on this owner's registration date at
322	     * the moment it was created, {@code false} otherwise. Captured at creation.
323	     */
324	    public boolean isBulkSignupWarning() {
325	        return this.bulkSignupWarning;
326	    }
327	
328	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
329	        this.bulkSignupWarning = bulkSignupWarning;
330	    }
331	
332	    /**
333	     * Whether this owner resembles an existing one: {@code true} when, at creation, it shared
334	     * an existing owner's postcode and a phonetically-equal last name ({@link Soundex Soundex})
335	     * yet differed in {@link #getIdentityKey() identity key} and was not a declared household
336	     * member, {@code false} otherwise. A declared member (created with {@code sharesHousehold})
337	     * is a genuine member, not a suspected duplicate. When true, {@link #getPossibleDuplicateOf()}
338	     * holds that owner's id. Captured at creation.
339	     */
340	    public boolean isPossibleDuplicate() {
341	        return this.possibleDuplicate;
342	    }
343	
344	    public void setPossibleDuplicate(boolean possibleDuplicate) {
345	        this.possibleDuplicate = possibleDuplicate;
346	    }
347	
348	    /**
349	     * The id of the existing owner this owner possibly duplicates (same postcode and a
350	     * phonetically-equal last name but a different {@link #getIdentityKey() identity key}), or
351	     * null when it is not a possible duplicate. Captured at creation.
352	     */
353	    public Integer getPossibleDuplicateOf() {
354	        return this.possibleDuplicateOf;
355	    }
356	
357	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
358	        this.possibleDuplicateOf = possibleDuplicateOf;
359	    }
360	
361	    /**
362	     * Whether this owner has been soft-deleted: {@code true} once a {@code DELETE} has
363	     * flagged the record (which is retained rather than removed), {@code false} for a live
364	     * owner. A newly created owner is not deleted. A deleted owner is still returned by
365	     * {@code GET}, but is ignored by the create endpoint's duplicate and identity checks.
366	     */
367	    public boolean isDeleted() {
368	        return this.deleted;
369	    }
370	
371	    public void setDeleted(boolean deleted) {
372	        this.deleted = deleted;
373	    }
374	
375	    /**
376	     * The owner's locality: the canonical region carried in the {@code <REGION>-<HASH8>}
377	     * customer code, i.e. the same region-and-hash identity used everywhere else. That
378	     * region was derived at creation by preferring the postcode range (NSW 2000-2099,
379	     * VIC 3000-3099, QLD 4000-4099), falling back to the fixed city-to-region table
380	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no
381	     * known range, or {@code "UNKNOWN"} otherwise. For an owner with no customer code the
382	     * region is derived directly from the stored postcode and city. Derived from stored
383	     * state, never persisted.
384	     */
385	    public String getLocality() {
386	        String region = CustomerCode.regionOf(this.customerCode);
387	        return region != null ? region : CityLocality.forPostcodeOrCity(this.postcode, this.city);
388	    }
389	
390	    /**
391	     * The owner's timezone: the IANA name for this owner's {@link #getLocality() locality}
392	     * via the fixed region-to-timezone table (NSW->Australia/Sydney,
393	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane), or {@code null} when the region
394	     * has no known timezone. Derived from stored state, never persisted.
395	     */
396	    public String getTimezone() {
397	        return RegionTimezone.forRegion(getLocality());
398	    }
399	
400	    /**
401	     * The owner's membership points, from 0 upwards: starts at 0, gains 2 when this owner
402	     * has an email address, gains 1 when this owner had no namesakes at creation
403	     * ({@code namesakeCount} is 0), gains 2 when this owner's household has 3 or more
404	     * members, and gains 3 once this owner's tenure spans at least one elapsed fiscal year.
405	     * A newly created owner has zero tenure, so it never earns those points at creation.
406	     * Derived from stored state, never persisted.
407	     */
408	    public int getMembershipPoints() {
