1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records the new owner's {@code bulkSignupWarning}: {@code true} when more than
9	 * {@value #BULK_SIGNUP_THRESHOLD} owners have already been registered on this owner's
10	 * registration date, {@code false} otherwise. Runs after {@link BuildOwner} (so the
11	 * entity and its rolled registration date exist) and before {@link SaveOwner} persists
12	 * the flag, so the freshly created owner is not counted among the day's registrations.
13	 * Registrations are counted via {@link Registrations}, the same accumulation path the
14	 * daily creation limit uses.
15	 */
16	public class AssignOwnerBulkSignupWarning {
17	
18	    static final int BULK_SIGNUP_THRESHOLD = 80;
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        long alreadyCreated = Registrations.countOn(ownerRepository, owner.getRegistrationDate());
22	        owner.setBulkSignupWarning(alreadyCreated > BULK_SIGNUP_THRESHOLD);
23	    }
24	}
