256	    /**
257	     * The owner's current primary identifier: the {@link #getCustomerCode() customer code} today.
258	     * The single source of truth for "which field identifies this owner", so a consumer such as the
259	     * {@code OWNER_CREATED} audit event always carries the right value; when the customer code is
260	     * later unified into a member id, this method returns that instead and every consumer follows
261	     * automatically. Derived from stored state, never persisted.
262	     */
263	    public String getPrimaryIdentifier() {
264	        return this.customerCode;
265	    }
266	
267	    /**
268	     * The stable identifier of the household this owner belongs to: the first twelve hex
269	     * characters of the SHA-256 of the normalized last name and postcode, so every owner
270	     * sharing a last name and postcode resolves to the same value. Null when the owner has
271	     * no postcode. Assigned at creation.
272	     */
273	    public String getHouseholdId() {
274	        return this.householdId;
275	    }
276	
277	    public void setHouseholdId(String householdId) {
278	        this.householdId = householdId;
279	    }
280	
281	    public Integer getNamesakeCount() {
282	        return this.namesakeCount;
283	    }
284	
285	    public void setNamesakeCount(Integer namesakeCount) {
286	        this.namesakeCount = namesakeCount;
287	    }
