305	    /**
306	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership level}: at
307	     * creation a new owner's level cannot exceed one above the highest level then held by an
308	     * existing member of its household (same last name and postcode). Null when no cap
309	     * applies, i.e. the household had no existing members. Captured at creation.
310	     */
311	    public Integer getMembershipLevelCap() {
312	        return this.membershipLevelCap;
313	    }
314	
315	    public void setMembershipLevelCap(Integer membershipLevelCap) {
316	        this.membershipLevelCap = membershipLevelCap;
317	    }
318	
319	    /**
320	     * Whether this owner was created as part of a bulk signup: {@code true} when more
321	     * than 80 owners had already been registered on this owner's registration date at
322	     * the moment it was created, {@code false} otherwise. Captured at creation.
323	     */
324	    public boolean isBulkSignupWarning() {
325	        return this.bulkSignupWarning;
326	    }
327	
328	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
329	        this.bulkSignupWarning = bulkSignupWarning;
330	    }
331	
332	    /**
333	     * Whether this owner resembles an existing one: {@code true} when, at creation, it shared
334	     * an existing owner's postcode and a phonetically-equal last name ({@link Soundex Soundex})
335	     * yet differed in {@link #getIdentityKey() identity key} and was not a declared household
336	     * member, {@code false} otherwise. A declared member (created with {@code sharesHousehold})
337	     * is a genuine member, not a suspected duplicate. When true, {@link #getPossibleDuplicateOf()}
338	     * holds that owner's id. Captured at creation.
339	     */
340	    public boolean isPossibleDuplicate() {
341	        return this.possibleDuplicate;
342	    }
343	
344	    public void setPossibleDuplicate(boolean possibleDuplicate) {
345	        this.possibleDuplicate = possibleDuplicate;
346	    }
