349	     * The id of the existing owner this owner possibly duplicates (same postcode and a
350	     * phonetically-equal last name but a different {@link #getIdentityKey() identity key}), or
351	     * null when it is not a possible duplicate. Captured at creation.
352	     */
353	    public Integer getPossibleDuplicateOf() {
354	        return this.possibleDuplicateOf;
355	    }
356	
357	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
358	        this.possibleDuplicateOf = possibleDuplicateOf;
359	    }
