361	    /**
362	     * Whether this owner has been soft-deleted: {@code true} once a {@code DELETE} has
363	     * flagged the record (which is retained rather than removed), {@code false} for a live
364	     * owner. A newly created owner is not deleted. A deleted owner is still returned by
365	     * {@code GET}, but is ignored by the create endpoint's duplicate and identity checks.
366	     */
367	    public boolean isDeleted() {
368	        return this.deleted;
369	    }
370	
371	    public void setDeleted(boolean deleted) {
372	        this.deleted = deleted;
373	    }
374	
375	    /**
376	     * The owner's locality: the canonical region carried in the {@code <REGION>-<HASH8>}
377	     * customer code, i.e. the same region-and-hash identity used everywhere else. That
378	     * region was derived at creation by preferring the postcode range (NSW 2000-2099,
379	     * VIC 3000-3099, QLD 4000-4099), falling back to the fixed city-to-region table
380	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no
381	     * known range, or {@code "UNKNOWN"} otherwise. For an owner with no customer code the
382	     * region is derived directly from the stored postcode and city. Derived from stored
383	     * state, never persisted.
384	     */
385	    public String getLocality() {
386	        String region = CustomerCode.regionOf(this.customerCode);
387	        return region != null ? region : CityLocality.forPostcodeOrCity(this.postcode, this.city);
388	    }
389	
390	    /**
391	     * The owner's timezone: the IANA name for this owner's {@link #getLocality() locality}
392	     * via the fixed region-to-timezone table (NSW->Australia/Sydney,
393	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane), or {@code null} when the region
394	     * has no known timezone. Derived from stored state, never persisted.
395	     */
396	    public String getTimezone() {
397	        return RegionTimezone.forRegion(getLocality());
398	    }
399	
400	    /**
401	     * The owner's membership points, from 0 upwards: starts at 0, gains 2 when this owner
402	     * has an email address, gains 1 when this owner had no namesakes at creation
403	     * ({@code namesakeCount} is 0), gains 2 when this owner's household has 3 or more
404	     * members, and gains 3 once this owner's tenure spans at least one elapsed fiscal year.
405	     * A newly created owner has zero tenure, so it never earns those points at creation.
406	     * Derived from stored state, never persisted.
407	     */
408	    public int getMembershipPoints() {
409	        int points = 0;
410	        if (hasEmail()) {
411	            points += 2;
412	        }
413	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
414	            points += 1;
415	        }
416	        if (this.householdSize != null && this.householdSize >= 3) {
417	            points += 2;
418	        }
419	        if (getTenureFiscalYears() >= 1) {
420	            points += 3;
421	        }
422	        return points;
423	    }
424	
425	    /**
426	     * The owner's fiscal year: the {@code FY<YY>} label (fiscal year starting 1 July,
427	     * identified by its ending calendar year) of the {@code registrationDate}, or
428	     * {@code null} when no registration date is recorded. Derived from stored state, never
429	     * persisted.
430	     */
431	    public String getFiscalYear() {
432	        return this.registrationDate == null ? null : FiscalYear.labelOf(this.registrationDate);
433	    }
434	
435	    /**
436	     * The owner's membership level, from 1 to 4: derived from {@link #getMembershipPoints()}
437	     * as level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more, then capped at
438	     * the {@link #getMembershipLevelCap() membership level cap} when one applies. Derived from
439	     * stored state, never persisted.
440	     */
441	    public int getMembershipLevel() {
442	        int level = uncappedMembershipLevel();
443	        return this.membershipLevelCap == null ? level : Math.min(level, this.membershipLevelCap);
444	    }
445	
446	    private int uncappedMembershipLevel() {
447	        int points = getMembershipPoints();
448	        if (points <= 1) {
449	            return 1;
450	        }
451	        if (points <= 3) {
452	            return 2;
453	        }
454	        if (points <= 5) {
455	            return 3;
456	        }
457	        return 4;
458	    }
459	
460	    /**
461	     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each
462	     * starting 1 July) between the {@code registrationDate} and the current server date, or
463	     * 0 when no registration date is recorded. Never negative in practice, since a future
464	     * registration date is rejected at creation.
465	     */
466	    private int getTenureFiscalYears() {
467	        if (this.registrationDate == null) {
468	            return 0;
469	        }
470	        return FiscalYear.elapsed(this.registrationDate, LocalDate.now());
471	    }
472	
473	    /**
474	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of
475	     * the {@code customerCode}. Derived from stored state, never persisted.
476	     */
477	    public int getCheckDigit() {
478	        return LuhnCheckDigit.of(this.customerCode);
479	    }
480	
481	    /**
482	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
483	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
484	     */
485	    public String getContactPreference() {
486	        return hasEmail() ? "EMAIL" : "PHONE";
487	    }
488	
489	    /**
490	     * The owner's identity key: the 64-character lower-case SHA-256 hex of the normalized
491	     * telephone, the lower-cased email (or empty when absent) and the {@link Soundex Soundex}
492	     * code of the last name, joined by {@code '|'}. Two owners collide on this key only when
493	     * they share a telephone, an email and a phonetically-equal surname, so it is the single
494	     * fingerprint the create endpoint's duplicate check keys off. Derived from stored state,
495	     * never persisted.
496	     */
497	    public String getIdentityKey() {
498	        String telephonePart = this.telephone == null ? "" : this.telephone;
499	        String emailPart = hasEmail() ? this.email.toLowerCase(Locale.ROOT) : "";
500	        String namePart = Soundex.of(getLastName());
501	        return Sha256.lowerHex(telephonePart + "|" + emailPart + "|" + namePart);
502	    }
503	
504	    private boolean hasEmail() {
505	        return this.email != null && !this.email.isEmpty();
506	    }
507	
508	    protected Set<Pet> getPetsInternal() {
509	        if (this.pets == null) {
510	            this.pets = new HashSet<>();
511	        }
512	        return this.pets;
513	    }
514	
515	    protected void setPetsInternal(Set<Pet> pets) {
516	        this.pets = pets;
517	    }
518	
519	    public List<Pet> getPets() {
520	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
521	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
522	        return Collections.unmodifiableList(sortedPets);
523	    }
524	
525	    public void setPets(List<Pet> pets) {
526	        this.pets = new HashSet<>(pets);
527	    }
528	
529	    public void addPet(Pet pet) {
530	        getPetsInternal().add(pet);
531	        pet.setOwner(this);
532	    }
533	
534	    /**
535	     * Return the Pet with the given name, or null if none found for this Owner.
536	     *
537	     * @param name to test
538	     * @return true if pet name is already in use
539	     */
540	    public Pet getPet(String name) {
541	        return getPet(name, false);
542	    }
543	
544	    /**
545	     * Return the Pet with the given name, or null if none found for this Owner.
546	     *
547	     * @param name to test
548	     * @return true if pet name is already in use
549	     */
550	    public Pet getPet(String name, boolean ignoreNew) {
551	        name = name.toLowerCase();
552	        for (Pet pet : getPetsInternal()) {
553	            if (!ignoreNew || !pet.isNew()) {
554	                String compName = pet.getName();
555	                compName = compName.toLowerCase();
556	                if (compName.equals(name)) {
557	                    return pet;
558	                }
559	            }
560	        }
561	        return null;
562	    }
563	
564	    public Pet getPet(Integer petId) {
565	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
566	    }
567	
568	    @Override
569	    public String toString() {
570	        return new ToStringCreator(this)
571	
572	            .append("id", this.getId())
573	            .append("new", this.isNew())
574	            .append("lastName", this.getLastName())
575	            .append("firstName", this.getFirstName())
576	            .append("address", this.address)
577	            .append("city", this.city)
578	            .append("telephone", this.telephone)
579	            .toString();
580	    }
581	}
