9	
10	/**
11	 * Rejects a create-owner request once the maximum number of owners ({@value #DAILY_LIMIT})
12	 * have already been registered on this request's business-day registration date, responding
13	 * 429, before {@link BuildOwner} persists one over the limit. Runs after
14	 * {@link RollRegistrationDateToBusinessDay} so the count is per adjusted business day.
15	 * Registrations are counted via {@link Registrations}.
16	 */
17	public class EnsureUnderDailyLimit {
18	
19	    static final int DAILY_LIMIT = 100;
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws DailyLimitExceededException {
23	        LocalDate date = request.getRegistrationDate();
24	        if (Registrations.countOn(ownerRepository, date) >= DAILY_LIMIT) {
25	            throw new DailyLimitExceededException(date, DAILY_LIMIT);
26	        }
27	    }
28	}
